        if nums:
            candidates[prio].append(nums[-1])

    for prio in [1, 2, 3, 4]:
        if candidates[prio]:
            value = candidates[prio][-1]
            try:
                return f"{float(value):.2f}"
            except ValueError:
                pass
    return None


def process(path):
    texts = ocr_image(path)
    date = None
    total = None
    for text in texts:
        if date is None:
            date = parse_date(text)
        if total is None:
            total = extract_total(text)
        if date and total:
            break
    return date, total


def main():
    rows = []
    for f in sorted(os.listdir(IMG_DIR)):
        if not f.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
