    (1, ['GRAND TOTAL']),
    (2, ['TOTAL RM', 'TOTAL: RM']),
    (3, ['TOTAL AMOUNT']),
    (4, ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT']),
]
EXCLUSION_KEYWORDS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

MONTHS = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
          'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}


def ocr_image(path):
    img = Image.open(path)
    texts = []
    for psm in (6, 4, 11):
        try:
            texts.append(pytesseract.image_to_string(img, config=f'--psm {psm}'))
        except Exception:
            pass
    return texts


def normalize_year(y):
    y = int(y)
    if y < 100:
        return 2000 + y if y < 50 else 1900 + y
    return y


DATE_DIGIT_MAP = str.maketrans({'O': '0', 'o': '0', 'D': '0',
                                'S': '5', 's': '5', 'l': '1', 'I': '1', 'i': '1',
                                'Z': '2', 'B': '8'})


def parse_date(text):
    # Allow OCR confusions (O/0, S/5, etc.) in date digit positions
    for m in re.finditer(r'(?<![\w/\-.])([\dOoSslLIiBZD]{1,2})[/\-.]([\dOoSslLIiBZD]{1,2})[/\-.]([\dOoSslLIiBZD]{2,4})(?!\w)',
                         text):
        raw_d, raw_m, raw_y = m.group(1), m.group(2), m.group(3)
        try:
            d = int(raw_d.translate(DATE_DIGIT_MAP))
            mo = int(raw_m.translate(DATE_DIGIT_MAP))
            y = normalize_year(raw_y.translate(DATE_DIGIT_MAP))
        except ValueError:
            continue
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2030:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    for m in re.finditer(r'(?<!\d)(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{2,4})(?!\d)',
                         text, re.IGNORECASE):
        d = int(m.group(1))
        mo = MONTHS[m.group(2).lower()[:3]]
        y = normalize_year(m.group(3))
        if 1 <= d <= 31 and 2000 <= y <= 2030:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def normalize_text(text):
    """Fix common OCR issues before line parsing."""
    text = re.sub(r'(\d)\s*\.\s*(\d{2})(?!\d)', r'\1.\2', text)
    text = re.sub(r'(\d)\s*,\s*(\d{2})(?!\d)', r'\1,\2', text)
    text = re.sub(r'\bT[uU0Oo]TAL\b', 'TOTAL', text)
    text = re.sub(r'\bTOTA[!1lI|]\b', 'TOTAL', text)
    return text


def extract_numbers(line):
    nums = re.findall(r'\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}', line)
    if nums:
        return [n.replace(',', '') for n in nums]
    nums = re.findall(r'(?<![\d,])\d{1,4},\d{2}(?![\d,])', line)
    return [n.replace(',', '.') for n in nums]


def preprocess_for_matching(line):
    pre = re.sub(r'\([^)]*\)', ' ', line)
    pre = re.sub(r'\bincl(?:usive)?\.?\s*(?:of\s+)?gst\b', ' ', pre, flags=re.IGNORECASE)
    pre = re.sub(r'\bexcl(?:uding|usive)?\.?\s*(?:of\s+)?gst\b', ' ', pre, flags=re.IGNORECASE)
    pre = re.sub(r'\bamt\b', 'amount', pre, flags=re.IGNORECASE)
    return pre.upper()


def is_excluded(line_pre):
    for kw in EXCLUSION_KEYWORDS:
        if re.search(r'\b' + re.escape(kw) + r'\b', line_pre):
            return True
    return False


def find_priority(line_pre):
    for prio, kws in PRIORITY_KEYWORDS:
        for kw in kws:
            if kw in line_pre:
                return prio
    return None


def extract_total(text):
    text = normalize_text(text)
    lines = text.split('\n')
    for i, line in enumerate(lines):
        if re.search(r'\bSUMMARY\b', line, re.IGNORECASE):
            lines = lines[:i]
            break

    candidates = {1: [], 2: [], 3: [], 4: []}
    for i, line in enumerate(lines):
        line_pre = preprocess_for_matching(line)
        if is_excluded(line_pre):
            continue
        prio = find_priority(line_pre)
        if prio is None:
            continue
        nums = extract_numbers(line)
        if not nums and i + 1 < len(lines):
            next_nums = extract_numbers(lines[i + 1])
            if next_nums:
                nums = [next_nums[-1]]
        if nums:
            candidates[prio].append(nums[-1])

    for prio in [1, 2, 3, 4]:
        if candidates[prio]:
            value = candidates[prio][-1]
            try:
                return f"{float(value):.2f}"
            except ValueError:
                pass
    return None


def process(path):
    texts = ocr_image(path)
    dates = []
    totals = []
    for text in texts:
        d = parse_date(text)
        if d:
            dates.append(d)
        t = extract_total(text)
        if t:
            totals.append(t)

    date = Counter(dates).most_common(1)[0][0] if dates else None
    total = Counter(totals).most_common(1)[0][0] if totals else None
    return date, total


def main():
    rows = []
    for f in sorted(os.listdir(IMG_DIR)):
        if not f.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
        date, total = process(os.path.join(IMG_DIR, f))
        rows.append({'filename': f, 'date': date, 'total_amount': total})
        print(f, date, total)

    df = pd.DataFrame(rows, columns=['filename', 'date', 'total_amount'])
    with pd.ExcelWriter(OUT_FILE, engine='openpyxl') as w:
        df.to_excel(w, sheet_name='results', index=False)


if __name__ == '__main__':
    main()
